import subprocess
import os
import glob
import time
def task_func(test_dir):
    results = {}
    if not isinstance(test_dir, str):
        return results
    dir_path = os.path.normpath(test_dir)
    if not os.path.isdir(dir_path):
        return results
    pattern = os.path.join(dir_path, '*.py')
    scripts = glob.glob(pattern)
    for script in scripts:
        name = os.path.basename(script)
        start = time.time()
        try:
            subprocess.run(['python', script], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=os.path.dirname(script))
            elapsed = time.time() - start
            results[name] = elapsed
        except Exception:
            results[name] = -1
    return results

