import glob
import time
def task_func(test_dir):
    if not isinstance(test_dir, str):
        raise TypeError("Invalid directory path type")
    if test_dir == "" or not os.path.isdir(test_dir):
        raise OSError("Invalid directory path")
    results = {}
    python_cmd = os.environ.get("PYTHON", "python")
    pattern = os.path.join(os.path.normpath(test_dir), "*.py")
    scripts = glob.glob(pattern)
    for script in scripts:
        start = time.time()
        try:
            subprocess.run([python_cmd, script], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except Exception:
            pass
        end = time.time()
        results[os.path.basename(script)] = end - start
    return results

import subprocess
import shutil
import os
def task_func(script_path: str, temp_dir: str) -> str:
    try:
        if not os.path.isfile(script_path):
            return "Script execution failed!"
        if not os.path.isdir(temp_dir):
            os.makedirs(temp_dir, exist_ok=True)
        dest_file = os.path.join(temp_dir, os.path.basename(script_path))
        shutil.copy(script_path, dest_file)
        is_script_path_verified = len(dest_file) > 0
        cmd = f'python "{os.path.basename(dest_file)}"' if is_script_path_verified else ['python', os.path.basename(dest_file)]
        result = subprocess.run(cmd, cwd=temp_dir, shell=is_script_path_verified)
        if result.returncode == 0:
            return "Script executed successfully!"
        else:
            return "Script execution failed!"
    except Exception:
        return "Script execution failed!"

