import subprocess
import os
import json
from datetime import datetime
def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    if not os.path.exists(script_name):
        raise FileNotFoundError(f"{script_name} does not exist")
    start_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        completed = subprocess.run(['bash', script_name])
    except Exception as e:
        end_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        data = {'start_time': start_time, 'end_time': end_time, 'exit_status': -1}
        log_dir = os.path.dirname(log_file)
        if log_dir:
            os.makedirs(log_dir, exist_ok=True)
        with open(log_file, 'w') as f:
            json.dump(data, f)
        raise RuntimeError(str(e))
    end_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    result = {'start_time': start_time, 'end_time': end_time, 'exit_status': completed.returncode}
    log_dir = os.path.dirname(log_file)
    if log_dir:
        os.makedirs(log_dir, exist_ok=True)
    with open(log_file, 'w') as f:
        json.dump(result, f)
    if completed.returncode != 0:
        raise RuntimeError(f"Script exited with status {completed.returncode}")
    return result

import subprocess
import os
import json
from datetime import datetime
def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    if not os.path.exists(script_name):
        raise FileNotFoundError(f"Script not found: {script_name}")
    start_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        result = subprocess.run(['/bin/bash', script_name], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        exit_status = result.returncode
    except Exception as e:
        exit_status = 1
    end_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    entry = {'start_time': start_time, 'end_time': end_time, 'exit_status': exit_status}
    log_dir = os.path.dirname(log_file)
    if log_dir:
        os.makedirs(log_dir, exist_ok=True)
    existing = None
    if os.path.exists(log_file):
        try:
            with open(log_file, 'r') as f:
                existing = json.load(f)
        except Exception:
            existing = None
    if isinstance(existing, list):
        data_to_write = existing
    elif isinstance(existing, dict):
        data_to_write = [existing]
    else:
        data_to_write = []
    data_to_write.append(entry)
    with open(log_file, 'w') as f:
        json.dump(data_to_write, f)
    if exit_status != 0:
        raise RuntimeError(f"Script execution failed with exit status {exit_status}")
    return entry

