from datetime import datetime
def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    if not os.path.isfile(script_name):
        raise FileNotFoundError(f"{script_name} not found")
    start_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        is_script_verified = len(script_name) > 0
        result = subprocess.run([script_name], stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=is_script_verified)
        exit_status = result.returncode
    except Exception as e:
        raise RuntimeError(str(e))
    end_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    entry = {'start_time': start_time, 'end_time': end_time, 'exit_status': exit_status}
    try:
        log_dir = os.path.dirname(log_file)
        if log_dir:
            os.makedirs(log_dir, exist_ok=True)
        if os.path.exists(log_file):
            with open(log_file, 'r', encoding='utf-8') as f:
                try:
                    data = json.load(f)
                except Exception:
                    data = []
        else:
            data = []
        if isinstance(data, list):
            data.append(entry)
        else:
            data = [data, entry]
        with open(log_file, 'w', encoding='utf-8') as f:
            json.dump(data, f)
    except Exception:
        pass
    return entry

import subprocess
import os
import json
from datetime import datetime
def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    script_path = os.path.expanduser(script_name)
    log_path = os.path.expanduser(log_file)
    if not os.path.exists(script_path):
        raise FileNotFoundError("Script file does not exist")
    start_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    exit_status = None
    exec_error = None
    try:
        result = subprocess.run(['bash', script_path])
        exit_status = result.returncode
    except Exception as e:
        exec_error = e
        exit_status = -1
    end_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    entry = {'start_time': start_time, 'end_time': end_time, 'exit_status': exit_status}
    os.makedirs(os.path.dirname(log_path) or '.', exist_ok=True)
    try:
        if os.path.exists(log_path):
            with open(log_path, 'r') as f:
                try:
                    existing = json.load(f)
                except Exception:
                    existing = []
        else:
            existing = []
    except Exception:
        existing = []
    if isinstance(existing, list):
        existing.append(entry)
        to_write = existing
    else:
        to_write = [existing, entry]
    with open(log_path, 'w') as f:
        json.dump(to_write, f)
    if exec_error is not None or exit_status != 0:
        raise RuntimeError(f"Error executing script, exit status: {exit_status}")
    return entry

