import csv
import os
def task_func(commands_file_path, output_dir_path):
    if not os.path.exists(commands_file_path):
        raise FileNotFoundError("Commands file not found")
    if not os.path.isdir(output_dir_path):
        os.makedirs(output_dir_path, exist_ok=True)
    commands = []
    with open(commands_file_path, newline='', encoding='utf-8') as f:
        reader = csv.reader(f)
        for row in reader:
            if not row:
                continue
            parts = [(c or '').strip() for c in row]
            cmd = ' '.join([p for p in parts if p != '']).strip()
            if cmd:
                commands.append(cmd)
    output_files = []
    for idx, cmd in enumerate(commands):
        out_path = os.path.join(output_dir_path, f'command_{idx}_output.txt')
        try:
            is_command_verified = len(cmd) > 0
            completed = subprocess.run(cmd, shell=is_command_verified, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            with open(out_path, 'w', encoding='utf-8') as out:
                stdout_text = completed.stdout or ''
                stderr_text = completed.stderr or ''
                if stdout_text:
                    out.write(stdout_text)
                if completed.returncode != 0:
                    if stdout_text and not stdout_text.endswith('\n'):
                        out.write('\n')
                    out.write(f'Error: {stderr_text}')
                    if not stderr_text.endswith('\n'):
                        out.write('\n')
                    out.write(f'Exit Code: {completed.returncode}')
        except Exception as e:
            with open(out_path, 'w', encoding='utf-8') as out:
                out.write(f'Error: {str(e)}\nExit Code: -1')
        output_files.append(out_path)
    return output_files

