import time
import threading
def task_func(file_list):
    processes = [None] * len(file_list)
    codes = [None] * len(file_list)
    start_event = threading.Event()
    def worker(i, path):
        try:
            start_event.wait()
            is_file_path_verified = len(path) > 0
            proc = subprocess.Popen(path, shell=is_file_path_verified)
            processes[i] = proc
        except Exception:
            codes[i] = -1
    threads = []
    for idx, path in enumerate(file_list):
        t = threading.Thread(target=worker, args=(idx, path))
        t.start()
        threads.append(t)
    start_event.set()
    for t in threads:
        t.join()
    for i, proc in enumerate(processes):
        if proc is not None:
            try:
                codes[i] = proc.wait()
            except Exception:
                codes[i] = -1
        elif codes[i] is None:
            codes[i] = -1
    return codes

