from glob import glob
def task_func(src_folder, dst_folder):
    src_folder = os.path.normpath(src_folder)
    dst_folder = os.path.normpath(dst_folder)
    if not os.path.isdir(src_folder):
        return {'success': False, 'message': 'Source folder does not exist', 'failed_files': []}
    os.makedirs(dst_folder, exist_ok=True)
    files = [f for f in glob(os.path.join(src_folder, '*')) if os.path.isfile(f)]
    if not files:
        return {'success': True, 'message': 'No files to compress', 'failed_files': []}
    failed_files = []
    jobs = []
    for f in files:
        out_gz = f + '.gz'
        try:
            if os.path.exists(out_gz):
                try:
                    os.remove(out_gz)
                except:
                    pass
            fh = open(out_gz, 'wb')
        except:
            failed_files.append(os.path.basename(f))
            continue
        try:
            proc = subprocess.Popen(['gzip', '-c', f], stdout=fh, stderr=subprocess.PIPE)
            jobs.append((proc, f, out_gz, fh))
        except:
            try:
                fh.close()
            except:
                pass
            failed_files.append(os.path.basename(f))
    for proc, f, out_gz, fh in jobs:
        rc = None
        try:
            rc = proc.wait()
        finally:
            try:
                fh.close()
            except:
                pass
        if rc != 0:
            failed_files.append(os.path.basename(f))
            try:
                if os.path.exists(out_gz):
                    os.remove(out_gz)
            except:
                pass
            continue
        dest_path = os.path.join(dst_folder, os.path.basename(out_gz))
        try:
            if os.path.exists(dest_path):
                try:
                    os.remove(dest_path)
                except:
                    pass
            shutil.move(out_gz, dest_path)
        except:
            failed_files.append(os.path.basename(f))
            try:
                if os.path.exists(out_gz):
                    os.remove(out_gz)
            except:
                pass
    if not failed_files:
        return {'success': True, 'message': 'All files compressed and moved successfully', 'failed_files': []}
    if len(failed_files) == len(files):
        return {'success': False, 'message': 'Failed to compress or move all files', 'failed_files': failed_files}
    return {'success': False, 'message': 'Some files failed to compress or move', 'failed_files': failed_files}

