import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("Invalid script_path type")
    if not script_path or not os.path.exists(script_path):
        raise OSError("Invalid script_path")
    proc = subprocess.Popen(['bash', script_path])
    p = psutil.Process(proc.pid)
    cpu_acc = 0.0
    mem_acc = 0
    last_rss = None
    try:
        p.cpu_percent(interval=None)
    except Exception:
        pass
    end_time = time.time() + float(timeout)
    interval = 0.1
    while True:
        if proc.poll() is not None:
            break
        if time.time() >= end_time:
            break
        try:
            s = p.status()
            if s == psutil.STATUS_ZOMBIE:
                break
        except psutil.NoSuchProcess:
            break
        time.sleep(interval)
        try:
            cpu_val = p.cpu_percent(interval=None)
            cpu_acc += float(cpu_val)
            mi = p.memory_info()
            rss = mi.rss
            if last_rss is None:
                last_rss = rss
            else:
                delta = rss - last_rss
                if delta > 0:
                    mem_acc += delta
                last_rss = rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess, psutil.AccessDenied):
            break
    if proc.poll() is None and time.time() >= end_time:
        try:
            proc.terminate()
        except Exception:
            pass
        try:
            proc.wait(timeout=1)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass
            try:
                proc.wait(timeout=1)
            except Exception:
                pass
    return {'CPU Usage': cpu_acc, 'Memory Usage': int(mem_acc)}

