        raise OSError("Invalid script path")
    try:
        is_script_path_verified = len(script_path) > 0
        proc = subprocess.Popen(['bash', script_path])
    except Exception:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}
    cpu_accum = 0.0
    mem_accum = 0
    prev_rss = None
    start = time.time()
    try:
        p = psutil.Process(proc.pid)
    except Exception:
        if proc.poll() is None:
            try:
                proc.terminate()
            except Exception:
                pass
        return {'CPU Usage': cpu_accum, 'Memory Usage': mem_accum}
    try:
        p.cpu_percent(interval=None)
    except Exception:
        pass
    interval = 0.5
    while True:
        if proc.poll() is not None:
            break
        if timeout is not None and (time.time() - start) >= timeout:
            break
        try:
            try:
                status = p.status()
                if status == psutil.STATUS_ZOMBIE:
                    break
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
            time.sleep(interval)
            try:
                cpu_val = p.cpu_percent(interval=None)
                cpu_accum += float(cpu_val)
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
            try:
                rss = p.memory_info().rss
                if prev_rss is None:
                    prev_rss = rss
                else:
                    if rss > prev_rss:
                        mem_accum += rss - prev_rss
                    prev_rss = rss
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
        except Exception:
            break
    if proc.poll() is None:
        try:
            proc.terminate()
        except Exception:
            pass
        try:
            proc.wait(timeout=2)
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass
