            if cpu is not None and cpu > 0:
                cpu_usage += cpu
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            time.sleep(0.1)
            continue
        except Exception:
            pass
        try:
            mem = p.memory_info().rss
            if last_rss is None:
                last_rss = mem
            else:
                if mem > last_rss:
                    memory_usage += mem - last_rss
                    last_rss = mem
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            pass
        except Exception:
            pass
    if process.poll() is None:
        try:
            process.terminate()
        except Exception:
            pass
        try:
            process.wait(timeout=1)
        except Exception:
            try:
                process.kill()
            except Exception:
                pass
    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("Invalid script path type")
    if not script_path or not os.path.exists(script_path):
        raise OSError("Invalid script path")
    cpu_accum = 0.0
    mem_accum = 0
    last_rss = None
    bash_exe = '/bin/bash' if os.path.exists('/bin/bash') else 'bash'
    try:
        proc = subprocess.Popen([bash_exe, script_path])
    except Exception:
        return {'CPU Usage': cpu_accum, 'Memory Usage': mem_accum}
    start = time.time()
    try:
        ps_proc = psutil.Process(proc.pid)
    except Exception:
        try:
            proc.wait(timeout=timeout)
        except Exception:
            try:
                proc.terminate()
            except Exception:
                pass
        return {'CPU Usage': cpu_accum, 'Memory Usage': mem_accum}
    try:
        ps_proc.cpu_percent(None)
    except Exception:
        pass
    sample_interval = 0.1
    while True:
        if proc.poll() is not None:
            break
        if time.time() - start >= timeout:
            break
        try:
            if not ps_proc.is_running():
                break
            try:
                status = ps_proc.status()
                if status == psutil.STATUS_ZOMBIE:
                    break
            except Exception:
                pass
            try:
                cpu = ps_proc.cpu_percent(interval=sample_interval)
                cpu_accum += float(cpu)
            except (psutil.NoSuchProcess, psutil.ZombieProcess, psutil.AccessDenied):
                break
            try:
                mem = ps_proc.memory_info().rss
                if last_rss is None:
                    last_rss = mem
                else:
                    if mem > last_rss:
                        mem_accum += mem - last_rss
                    last_rss = mem
            except (psutil.NoSuchProcess, psutil.ZombieProcess, psutil.AccessDenied):
                break
        except (psutil.NoSuchProcess, psutil.ZombieProcess, psutil.AccessDenied):
            break
    if proc.poll() is None and time.time() - start >= timeout:
        try:
            proc.terminate()
            try:
                proc.wait(timeout=1)
            except subprocess.TimeoutExpired:
                try:
                    proc.kill()
                except Exception:
                    pass
        except Exception:
            try:
                proc.kill()
            except Exception:
                pass
    return {'CPU Usage': cpu_accum, 'Memory Usage': int(mem_accum)}

import subprocess
import logging
def task_func(filepath):
    logging.basicConfig(level=logging.INFO, format="%(levelname)s: %(message)s")
    try:
        f = open(filepath, 'r')
        f.close()
    except FileNotFoundError:
        logging.error("Source file not found: %s", filepath)
        raise
    compiler = None
    for c in ["g++", "clang++"]:
        try:
            subprocess.run([c, "--version"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            compiler = c
            break
        except FileNotFoundError:
            continue
    if compiler is None:
        logging.error("No C++ compiler found (g++/clang++)")
        raise FileNotFoundError("C++ compiler not found")
    sep_f = max(filepath.rfind('/'), filepath.rfind('\\'))
    name = filepath[sep_f + 1:] if sep_f != -1 else filepath
    dot = name.rfind('.')
    base = name[:dot] if dot != -1 else name
    dir_path = filepath[:sep_f + 1] if sep_f != -1 else ""
    out_path = dir_path + base
    try:
        result = subprocess.run([compiler, filepath, "-o", out_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, check=True)
        logging.info("Compilation successful: %s -> %s", filepath, out_path)
        if result.stdout.strip():
            logging.info("Compiler output: %s", result.stdout.strip())
    except subprocess.CalledProcessError as e:
        logging.error("Compilation failed with return code %s", e.returncode)
        if e.stdout and e.stdout.strip():
            logging.error("stdout: %s", e.stdout.strip())
        if e.stderr and e.stderr.strip():
            logging.error("stderr: %s", e.stderr.strip())
        raise
    return None

import subprocess
import logging
def task_func(filepath):
    logging.basicConfig(level=logging.INFO, format='%(levelname)s: %(message)s')
    try:
        f = open(filepath, 'rb')
        f.close()
    except FileNotFoundError:
        raise
    name_part = filepath.replace('\\', '/').split('/')[-1]
    base_name = name_part.rsplit('.', 1)[0]
    compilers = ['g++', 'clang++', 'cl']
    logging.info(f'Starting compilation for {filepath}')
    for comp in compilers:
        try:
            if comp in ('g++', 'clang++'):
                cmd = [comp, filepath, '-o', base_name]
            else:
                cmd = [comp, '/nologo', '/EHsc', filepath, '/Fe:' + base_name + '.exe']
            result = subprocess.run(cmd, capture_output=True, text=True, check=True)
            if result.stdout:
                logging.info(result.stdout.strip())
            if result.stderr:
                logging.info(result.stderr.strip())
            logging.info(f'Compilation succeeded using {comp}')
            return
        except FileNotFoundError:
            continue
        except subprocess.CalledProcessError as e:
            out = e.stdout.strip() if e.stdout else ''
            err = e.stderr.strip() if e.stderr else ''
            if out:
                logging.error(out)
            if err:
                logging.error(err)
            logging.error(f'Compilation failed using {comp}')
            raise
    raise FileNotFoundError('No supported C++ compiler found')

